import sys,json,tempfile,hashlib
from pathlib import Path
sys.path.insert(0,str(Path.cwd()/'scripts'))
from semantic_lsp import LspProcess
class Trace(LspProcess):
 def __init__(self,*args):self.raw=[];super().__init__(*args)
 def _dispatch(self,body,received_ns):self.raw.append(json.loads(body));return super()._dispatch(body,received_ns)
def location_key(item):
 r=item['range'];return(item['uri'],r['start']['line'],r['start']['character'],r['end']['line'],r['end']['character'])
binary=Path('/workspace/target/semantic-approved-126952f6d048/debug/bend2-lsp')
with binary.open('rb') as stream:binary_sha=hashlib.file_digest(stream,'sha256').hexdigest()
with tempfile.TemporaryDirectory(prefix='integrated-discovery-functional-') as directory:
 root=Path(directory);common=root/'common.bend';common_uri=common.as_uri()
 original='def identity(value: U32) -> U32:\n  value\n'.replace('\\n','\n')
 original='def identity(value: U32) -> U32:\n  value\n'.encode().decode('unicode_escape')
 common.write_text(original)
 expected_symbols={('identity',common_uri,0,4,0,12)}
 expected_references={(common_uri,0,4,0,12)}
 for index in range(9999):
  name=f'consumer_{index:04}';path=root/(name+'.bend')
  path.write_text(f'import ./common.bend as Common\ndef {name}() -> U32:\n  Common.identity(1)\n'.encode().decode('unicode_escape'))
  expected_symbols.add((name,path.as_uri(),1,4,1,4+len(name)))
  expected_references.add((path.as_uri(),2,9,2,17))
 client=Trace(binary,root);stage='initialize';payload={}
 try:
  client.initialize()
  stage='cold symbols'
  symbols,_=client.request('workspace/symbol',{'query':''})
  actual={(item['name'],*location_key(item['location'])) for item in symbols}
  assert len(symbols)==10000 and actual==expected_symbols,{'stage':stage,'count':len(symbols),'missing':list(expected_symbols-actual)[:3],'extra':list(actual-expected_symbols)[:3]}
  payload['cold_symbols']={'count':len(symbols),'exact_names_locations':True}
  client.notify('textDocument/didOpen',{'textDocument':{'uri':common_uri,'languageId':'bend','version':1,'text':original}})
  stage='cold references'
  params={'textDocument':{'uri':common_uri},'position':{'line':0,'character':6},'context':{'includeDeclaration':True}}
  references,_=client.request('textDocument/references',params)
  actual={location_key(item) for item in references}
  assert len(references)==10000 and actual==expected_references,{'stage':stage,'count':len(references),'missing':list(expected_references-actual)[:3],'extra':list(actual-expected_references)[:3]}
  payload['cold_references']={'count':len(references),'exact_locations_no_duplicates':True}
  changed='def identity(value: U32) -> U32:\n  (value + 0)\n'.encode().decode('unicode_escape')
  client.notify('textDocument/didChange',{'textDocument':{'uri':common_uri,'version':2},'contentChanges':[{'text':changed}]})
  stage='unsaved dependency revision'
  references,_=client.request('textDocument/references',params)
  actual={location_key(item) for item in references}
  assert len(references)==10000 and actual==expected_references,{'stage':stage,'count':len(references),'missing':list(expected_references-actual)[:3],'extra':list(actual-expected_references)[:3]}
  payload['after_unsaved_dependency_revision']={'version':2,'count':len(references),'exact_locations_no_duplicates':True}
  client.notify('textDocument/didClose',{'textDocument':{'uri':common_uri}})
  client.notify('workspace/didChangeWorkspaceFolders',{'event':{'added':[],'removed':[{'uri':root.as_uri(),'name':'semantic'}]}})
  stage='root removal'
  symbols,_=client.request('workspace/symbol',{'query':''})
  assert symbols==[],{'stage':stage,'count':len(symbols)}
  payload['root_removal']={'symbols':0}
  stage='shutdown';client.finish();payload['exit']=client.process.returncode
  result={'scope':'Actual10000-fileLSPcorrectnessonly; no local latency/RSS qualification; compiler unavailability isolated by existinghelper, not compiler acceptance','files':10000,'binary_sha256':binary_sha,'payload':payload,'raw_messages':client.raw,'stderr':client.stderr_tail()}
 except BaseException:
  print(json.dumps({'failed_stage':stage,'payload':payload,'raw_messages':client.raw,'stderr':client.stderr_tail()}));raise
 finally:client.close()
print(json.dumps(result))
